public class Wizard {
    private String name;
    private int mana;

    public Wizard(String name, int mana) {
        this.name = name;
        this.mana = mana;
    }

    public void castSpell() {
        mana -= 10;
        System.out.println(name + " casts!");
    }
}

Wizard lyria = new Wizard("Lyria", 100);
Wizard drake = new Wizard("Drake", 50);
lyria.castSpell(); // Lyria casts!
System.out.println(lyria.getMana()); // 90

